import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matvec_f32(
    .param .u64 .ptr .align 8 param_A,
    .param .u64 .ptr .align 8 param_B,
    .param .u64 .ptr .align 8 param_C,
    .param .u32 param_M,
    .param .u32 param_K
)
.reqntid 128
{
    .reg .pred %p<4>;
    .reg .b32  %r<16>;
    .reg .b64  %rd<16>;
    .reg .f32  %f<16>;

    .shared .align 4 .b8 smem[1024];

    ld.param.u64 %rd1, [param_A];
    ld.param.u64 %rd2, [param_B];
    ld.param.u64 %rd3, [param_C];
    ld.param.u32 %r1,  [param_M];
    ld.param.u32 %r2,  [param_K];

    mov.u32 %r3, %tid.x;
    mov.u32 %r4, %ctaid.x;
    mov.u32 %r5, %ntid.x;

    // One block per output row; guard partial/out-of-range blocks.
    setp.ge.u32 %p1, %r4, %r1;
    @%p1 bra DONE;

    // K4 = K / 4 (K is a multiple of 4 for the target shapes).
    shr.u32 %r6, %r2, 2;

    // Row base pointer: A + row * K (elements) * 4 bytes.
    mul.wide.u32 %rd4, %r4, %r2;
    shl.b64 %rd4, %rd4, 2;
    add.u64 %rd4, %rd4, %rd1;

    // Generic address of shared reduction buffer.
    mov.u64 %rd8, smem;

    mov.f32 %f1, 0f00000000;
    mov.u32 %r7, %r3;

LOOP:
    setp.ge.u32 %p1, %r7, %r6;
    @%p1 bra RED;
    mul.wide.u32 %rd5, %r7, 16;
    add.u64 %rd6, %rd4, %rd5;
    add.u64 %rd7, %rd2, %rd5;
    ld.global.v4.f32 {%f2, %f3, %f4, %f5}, [%rd6];
    ld.global.v4.f32 {%f6, %f7, %f8, %f9}, [%rd7];
    fma.rn.f32 %f1, %f2, %f6, %f1;
    fma.rn.f32 %f1, %f3, %f7, %f1;
    fma.rn.f32 %f1, %f4, %f8, %f1;
    fma.rn.f32 %f1, %f5, %f9, %f1;
    add.u32 %r7, %r7, %r5;
    bra LOOP;

RED:
    // Store per-thread partial sums into shared memory.
    mul.wide.u32 %rd9, %r3, 4;
    add.u64 %rd9, %rd9, %rd8;
    st.shared.f32 [%rd9], %f1;
    bar.sync 0;

    // Tree reduction over 128 threads (fixed block size).
    mov.u32 %r8, 64;
RLOOP:
    setp.ge.u32 %p1, %r3, %r8;
    @%p1 bra RSKIP;
    add.u32 %r9, %r3, %r8;
    mul.wide.u32 %rd10, %r9, 4;
    add.u64 %rd10, %rd10, %rd8;
    ld.shared.f32 %f10, [%rd10];
    add.f32 %f1, %f1, %f10;
    st.shared.f32 [%rd9], %f1;
RSKIP:
    bar.sync 0;
    shr.u32 %r8, %r8, 1;
    setp.ne.u32 %p1, %r8, 0;
    @%p1 bra RLOOP;

    // Thread 0 writes the row result.
    setp.ne.u32 %p1, %r3, 0;
    @%p1 bra DONE;
    mul.wide.u32 %rd10, %r4, 4;
    add.u64 %rd10, %rd10, %rd3;
    st.global.f32 [%rd10], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matvec_f32")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M, K = A.shape
        C = torch.empty((M, 1), dtype=A.dtype, device=A.device)
        module = _get_ptx_module()
        module.launch(
            "matvec_f32",
            grid=(M, 1, 1),
            block=(128, 1, 1),
            arguments=[A, B, C, u32(M), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

